/// The time-windowed family across all three expansions, not just two.
///
/// Worth doing here rather than leaning on the block above: these ops evict by
/// *engine time*, and an island reads the outer engine's clock rather than
/// keeping its own, so `nested` is the expansion where a window could plausibly
/// disagree. It does not.
#[cfg(feature = "statistics")]
#[test]
fn stats_time_windowed_reaches_a_nested_island() {
    let (mut runner, out) = surface_stats_time_windowed::interpreted();
    runner.run(HISTORICAL, RUN).unwrap();
    let interp = runner.value(out);
    assert!(
        !interp.is_empty(),
        "surface_stats_time_windowed had no values"
    );

    let g = GraphBuilder::new();
    let island = surface_stats_time_windowed::nested(&g);
    let mut r = g.build();
    r.run(HISTORICAL, RUN).unwrap();
    assert_eq!(
        interp,
        r.value(&island),
        "interpreted vs nested drift in surface_stats_time_windowed"
    );
}

// --- The execution nodes ----------------------------------------------------
//
// `oms_op`, `algo_op`, `fix_bridge_op`, `sim_venue_op`, `position_op`,
// `reconcile_op` and `switch_op` are `#[op]`s whose fluent faces
// (`wire_oms`/`oms`, `algo`, `fix_bridge`, `SimVenue::wire`,
// `wire_position`/`position`, `wire_reconcile`/`reconcile`, `kill_switch`)
// return several streams filtered off one node or build through a wiring
// builder, which `nitro!`'s grammar cannot bind. The ops are public so a
// compiled graph can name them, and this block does: each is spelled at its
// build name through a one-line fluent method below, so both the forwarders
// and every tier are exercised.
#[cfg(feature = "execution-testing")]
mod execution {
    use super::*;

    use wingfoil::trading::execution::algo::node::*;
    use wingfoil::trading::execution::algo::{Parent, Progress};
    use wingfoil::trading::execution::edge::{Report, Request, TradingState};
    use wingfoil::trading::execution::fix::node::*;
    use wingfoil::trading::execution::fix::{ExecReport, Message};
    use wingfoil::trading::execution::oms::node::*;
    use wingfoil::trading::execution::oms::{Config, Desired, Oms, Pacing, Slot};
    use wingfoil::trading::execution::order::{ClientOrderId, Epoch};
    use wingfoil::trading::execution::rate_limit::{OrderRate, Terms};
    use wingfoil::trading::execution::testing::*;
    use wingfoil::trading::market::{Px, Qty, Side};

    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
    pub struct Es;

    type OmsOut = (Burst<Request<Es>>, Pacing, Slot<Es>);
    type AlgoOut = (Burst<Desired<Es>>, Burst<Progress<Es>>);
    type ChainOut = (Burst<Message<Es>>, Burst<Report<Es>>);
    type VenueOut = (NanoTime, Burst<Report<Es>>);
    type Cycle = (AlgoOut, OmsOut, VenueOut, ChainOut);

    const RATE: OrderRate =
        OrderRate::stated(Terms::per_second(100, 100), Terms::per_second(1, 1), 1.0);

    fn config() -> Config {
        Config::unmetered()
            .with_rate(RATE)
            .with_max_desired_age(Duration::from_secs(60))
    }

    fn px(s: &str) -> Px {
        Px::parse(s).unwrap()
    }

    fn one<T: Default>(value: T) -> Burst<T> {
        let mut burst = Burst::new();
        burst.push(value);
        burst
    }

    /// Buy 2 at once, crossing up to 101, done by 100ms.
    fn parent() -> Burst<Parent<Es>> {
        let by = NanoTime::new(100_000_000);
        one(Parent::sweep(Es, Side::Bid, Qty::parse("2").unwrap(), px("101"), by).unwrap())
    }

    /// What the OMS reads back: its bid slot. A fn item rather than a
    /// closure, because `nitro!` takes a literal closure as the whole `Cfg`
    /// and this one is the last field of `oms_op`'s.
    fn bid_slot(oms: &Oms<Es>) -> Slot<Es> {
        oms.slot(&Es, Side::Bid)
    }

    fn touch() -> Burst<Touch<Es>> {
        one(Touch {
            instrument: Es,
            bid: Some(px("100")),
            ask: Some(px("100.25")),
        })
    }

    pub trait RequestNodes {
        fn algo_op(
            &self,
            reports: &Stream<Burst<Report<Es>>>,
            parents: &Stream<Burst<Parent<Es>>>,
            clock: &Stream<()>,
        ) -> Stream<AlgoOut>;
    }

    impl RequestNodes for Stream<Burst<Request<Es>>> {
        fn algo_op(
            &self,
            reports: &Stream<Burst<Report<Es>>>,
            parents: &Stream<Burst<Parent<Es>>>,
            clock: &Stream<()>,
        ) -> Stream<AlgoOut> {
            let (reports, parents, clock) = (reports.handle(), parents.handle(), clock.handle());
            self.wire(move |b, landed| b.algo_op(landed, reports, parents, clock))
        }
    }

    pub trait ReportNodes {
        #[allow(clippy::too_many_arguments)]
        fn oms_op<F: Fn(&Oms<Es>) -> Slot<Es> + 'static>(
            &self,
            trading: &Stream<TradingState>,
            cancel_all: &Stream<()>,
            desired: &Stream<Burst<Desired<Es>>>,
            sweep: &Stream<()>,
            config: Config,
            epoch: Epoch,
            read: F,
        ) -> Stream<OmsOut>;
    }

    impl ReportNodes for Stream<Burst<Report<Es>>> {
        fn oms_op<F: Fn(&Oms<Es>) -> Slot<Es> + 'static>(
            &self,
            trading: &Stream<TradingState>,
            cancel_all: &Stream<()>,
            desired: &Stream<Burst<Desired<Es>>>,
            sweep: &Stream<()>,
            config: Config,
            epoch: Epoch,
            read: F,
        ) -> Stream<OmsOut> {
            let (trading, cancel_all, desired, sweep) = (
                trading.handle(),
                cancel_all.handle(),
                desired.handle(),
                sweep.handle(),
            );
            self.wire(move |b, reports| {
                b.oms_op(
                    reports,
                    trading,
                    cancel_all,
                    desired,
                    sweep,
                    (config, epoch, read),
                )
            })
        }
    }

    pub trait TradingNodes {
        fn sim_venue_op(
            &self,
            touch: &Stream<Burst<Touch<Es>>>,
            requests: &Stream<Burst<Request<Es>>>,
            profile: Profile,
            epoch: Epoch,
        ) -> Stream<Burst<Report<Es>>>;
    }

    impl TradingNodes for Stream<TradingState> {
        fn sim_venue_op(
            &self,
            touch: &Stream<Burst<Touch<Es>>>,
            requests: &Stream<Burst<Request<Es>>>,
            profile: Profile,
            epoch: Epoch,
        ) -> Stream<Burst<Report<Es>>> {
            let (touch, requests) = (touch.handle(), requests.handle());
            self.wire(move |b, states| b.sim_venue_op(states, touch, requests, (profile, epoch)))
        }
    }

    pub trait ExecutionNodes {
        fn fix_bridge_op(
            &self,
            requests: &Stream<Burst<Request<Es>>>,
            mass_cancel: bool,
            epoch: Epoch,
        ) -> Stream<ChainOut>;
    }

    impl ExecutionNodes for Stream<Burst<ExecReport<Es>>> {
        fn fix_bridge_op(
            &self,
            requests: &Stream<Burst<Request<Es>>>,
            mass_cancel: bool,
            epoch: Epoch,
        ) -> Stream<ChainOut> {
            let requests = requests.handle();
            self.wire(move |b, executions| {
                b.fix_bridge_op(executions, requests, (mass_cancel, epoch))
            })
        }
    }

    // A parent into the algos, their desireds into the OMS, its requests into
    // both the test venue and a FIX bridge. The reports into the algos and
    // the OMS, and the requests landed back at the algos, are streams that
    // never tick: closing either loop would need `feedback`, which a compiled
    // graph cannot express (category 1).
    wingfoil::nitro! {
        fn surface_execution(g: &GraphBuilder) -> Stream<Vec<(NanoTime, Cycle)>> {
            let count = g.ticker(P).count();
            let clock = count.map(|_| ());
            let parents = count.map_filter(|c: &u64| (parent(), *c == 1));
            let touches = count.map_filter(|c: &u64| (touch(), *c == 1));
            let landed = count.map_filter(|_| (Burst::<Request<Es>>::new(), false));
            let reports = count.map_filter(|_| (Burst::<Report<Es>>::new(), false));
            let executions = count.map_filter(|_| (Burst::<ExecReport<Es>>::new(), false));
            let trading = count.map_filter(|_| (TradingState::Open, false));
            let pull = count.map_filter(|_| ((), false));
            let algo = landed.algo_op(&reports, &parents, &clock);
            let desired = algo.map(|(desired, _): &AlgoOut| desired.clone());
            let oms = reports.oms_op(
                &trading,
                &pull,
                &desired,
                &clock,
                config(),
                Epoch::ZERO,
                bid_slot,
            );
            let requests = oms.map(|(requests, _, _): &OmsOut| requests.clone());
            let venue = trading.sim_venue_op(&touches, &requests, Profile::EXCHANGE, Epoch::ZERO);
            let bridge = executions.fix_bridge_op(&requests, false, Epoch::ZERO);
            // The venue ticks only on a cycle with reports, so the join reads a
            // held burst on the others; its tick time says which.
            let venue_at = venue.with_time();
            let front = algo.join3(&oms, &venue_at, |a: &AlgoOut, o: &OmsOut, v: &VenueOut| {
                (a.clone(), o.clone(), v.clone())
            });
            let all = front.join(&bridge, |(a, o, v): &(AlgoOut, OmsOut, VenueOut), c: &ChainOut| {
                (a.clone(), o.clone(), v.clone(), c.clone())
            });
            let out = all.with_time().accumulate();
            out
        }
    }

    /// One cycle, condensed: the desireds the algos emitted and the clips on
    /// each progress row, what the OMS sent and whether its bid slot holds
    /// order 1 in flight, the venue's last answer and when it ticked, and the
    /// price of each message the bridge rendered.
    type Row = (
        NanoTime,
        usize,
        Vec<u32>,
        Vec<Option<Px>>,
        bool,
        (NanoTime, Vec<Option<(Qty, Px)>>),
        Vec<Option<Px>>,
    );

    fn row(
        (at, ((desired, progress), (requests, _, slot), (answered, venue), (messages, _))): &(
            NanoTime,
            Cycle,
        ),
    ) -> Row {
        let first = ClientOrderId::new(Epoch::ZERO, 1);
        (
            *at,
            desired.len(),
            progress.iter().map(|p| p.clips).collect(),
            requests
                .iter()
                .map(|r| match r {
                    Request::Place(order) if order.id == first => order.price,
                    other => panic!("unexpected request {other:?}"),
                })
                .collect(),
            matches!(slot, Slot::Pending(placed) if placed.id == first),
            (
                *answered,
                venue
                    .iter()
                    .map(|r| match r {
                        Report::Ack(ack) if ack.order == first => None,
                        Report::Fill(fill) if fill.order == first => Some((fill.qty, fill.price)),
                        other => panic!("unexpected report {other:?}"),
                    })
                    .collect(),
            ),
            messages
                .iter()
                .map(|m| match m {
                    Message::New(new) => new.price,
                    other => panic!("unexpected message {other:?}"),
                })
                .collect(),
        )
    }

    /// The parent sweeps at once: one desired crossing to 101, the OMS
    /// places it, the venue acks and fills all 2 at the 100.25 ask, the
    /// bridge renders the same order as a FIX new. With no reports fed back,
    /// the slot stays in flight and the later cycles send nothing; the venue
    /// stays quiet, so they read its 0ms answer, held.
    #[test]
    fn execution_surface_three_engine_parity() {
        let run = RunFor::Cycles(3);
        let (mut runner, out) = surface_execution::interpreted();
        runner.run(HISTORICAL, run).unwrap();
        let interp = runner.value(out);
        let answered = (
            NanoTime::ZERO,
            vec![None, Some((Qty::parse("2").unwrap(), px("100.25")))],
        );
        let expected: Vec<Row> = vec![
            (
                NanoTime::ZERO,
                1,
                vec![0, 1],
                vec![Some(px("101"))],
                true,
                answered.clone(),
                vec![Some(px("101"))],
            ),
            (
                NanoTime::new(10_000_000),
                0,
                vec![],
                vec![],
                true,
                answered.clone(),
                vec![],
            ),
            (
                NanoTime::new(20_000_000),
                0,
                vec![],
                vec![],
                true,
                answered,
                vec![],
            ),
        ];
        assert_eq!(interp.iter().map(row).collect::<Vec<_>>(), expected);

        let (compiled,) = surface_execution::compiled(HISTORICAL, run).unwrap();
        assert_eq!(
            interp, compiled,
            "interpreted vs compiled drift in surface_execution"
        );

        let g = GraphBuilder::new();
        let island = surface_execution::nested(&g);
        let mut r = g.build();
        r.run(HISTORICAL, run).unwrap();
        assert_eq!(
            interp,
            r.value(&island),
            "interpreted vs nested drift in surface_execution"
        );
    }

    // --- The risk nodes: the position fold, reconciliation, the kill switch.

    use wingfoil::trading::execution::edge::{Cashflow, Held, Holdings};
    use wingfoil::trading::execution::exec_id::ExecId;
    use wingfoil::trading::execution::kill_switch::node::*;
    use wingfoil::trading::execution::kill_switch::{
        Assessed, Breaches, Limit, Snapshot, Stance, Switch,
    };
    use wingfoil::trading::execution::order::{Fill, Liquidity};
    use wingfoil::trading::execution::position::node::*;
    use wingfoil::trading::execution::position::{Book, Measure};
    use wingfoil::trading::execution::reconcile::node::*;
    use wingfoil::trading::execution::reconcile::{self, Mismatch};

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Risk {
        Mismatch,
    }

    impl Limit for Risk {
        const ALL: &'static [Risk] = &[Risk::Mismatch];
    }

    /// `(heard, disagreeing, rebased, net)`.
    type Standing = (bool, usize, u64, Qty);
    type ReconcileOut = (Burst<Mismatch<Es>>, Standing);
    type RiskCycle = (Qty, ReconcileOut, Assessed<Risk>);

    fn qty(s: &str) -> Qty {
        Qty::parse(s).unwrap()
    }

    /// Fifty a point. A fn item, like `bid_slot`, because it sits in a `Cfg`.
    fn es_measure(_: &Es) -> Option<Measure> {
        Measure::scaled(qty("50"))
    }

    fn es_net(book: &Book<Es>) -> Qty {
        book.net(&Es)
    }

    fn es_standing(desk: &Desk<Es>) -> Standing {
        let reconciler = desk.reconciler();
        (
            reconciler.has_heard(),
            reconciler.disagreeing(),
            reconciler.rebased(),
            desk.book().net(&Es),
        )
    }

    /// A mismatch is a breach.
    fn es_assess(_: &mut Switch<Risk>, _: NanoTime, mismatches: &usize) -> Breaches<Risk> {
        let mut standing = Breaches::NONE;
        if *mismatches > 0 {
            standing.set(Risk::Mismatch);
        }
        standing
    }

    /// The fold may disagree with the venue for one tick.
    fn grace() -> reconcile::Config {
        reconcile::Config { grace: P }
    }

    /// Two lots bought at 5000.
    fn es_fill() -> Burst<Fill<Es>> {
        one(Fill {
            order: ClientOrderId::new(Epoch::ZERO, 1),
            exec_id: ExecId::new("e").unwrap(),
            instrument: Es,
            side: Side::Bid,
            qty: qty("2"),
            filled: qty("2"),
            remaining: Qty::ZERO,
            price: px("5000"),
            liquidity: Liquidity::Maker,
            ..Default::default()
        })
    }

    fn es_cashflow() -> Burst<Cashflow<Es>> {
        one(Cashflow {
            instrument: Es,
            amount: qty("-1"),
            ..Cashflow::default()
        })
    }

    /// The venue holds three.
    fn es_holdings() -> Burst<Holdings<Es>> {
        one(Holdings {
            whole: true,
            held: one(Held {
                instrument: Es,
                net: qty("3"),
            }),
            as_of: NanoTime::ZERO,
        })
    }

    fn es_marks() -> Burst<(Es, Px)> {
        one((Es, px("5001")))
    }

    pub trait FillNodes {
        fn position_op<M, F>(
            &self,
            settlements: &Stream<Burst<Fill<Es>>>,
            cashflows: &Stream<Burst<Cashflow<Es>>>,
            measure: M,
            read: F,
        ) -> Stream<Qty>
        where
            M: Fn(&Es) -> Option<Measure> + Clone + 'static,
            F: Fn(&Book<Es>) -> Qty + 'static;

        #[allow(clippy::too_many_arguments)]
        fn reconcile_op<M, F>(
            &self,
            settlements: &Stream<Burst<Fill<Es>>>,
            cashflows: &Stream<Burst<Cashflow<Es>>>,
            holdings: &Stream<Burst<Holdings<Es>>>,
            marks: &Stream<Burst<(Es, Px)>>,
            sweep: &Stream<()>,
            config: reconcile::Config,
            measure: M,
            read: F,
        ) -> Stream<ReconcileOut>
        where
            M: Fn(&Es) -> Option<Measure> + Clone + 'static,
            F: Fn(&Desk<Es>) -> Standing + 'static;
    }

    impl FillNodes for Stream<Burst<Fill<Es>>> {
        fn position_op<M, F>(
            &self,
            settlements: &Stream<Burst<Fill<Es>>>,
            cashflows: &Stream<Burst<Cashflow<Es>>>,
            measure: M,
            read: F,
        ) -> Stream<Qty>
        where
            M: Fn(&Es) -> Option<Measure> + Clone + 'static,
            F: Fn(&Book<Es>) -> Qty + 'static,
        {
            let (settlements, cashflows) = (settlements.handle(), cashflows.handle());
            self.wire(move |b, fills| b.position_op(fills, settlements, cashflows, (measure, read)))
        }

        fn reconcile_op<M, F>(
            &self,
            settlements: &Stream<Burst<Fill<Es>>>,
            cashflows: &Stream<Burst<Cashflow<Es>>>,
            holdings: &Stream<Burst<Holdings<Es>>>,
            marks: &Stream<Burst<(Es, Px)>>,
            sweep: &Stream<()>,
            config: reconcile::Config,
            measure: M,
            read: F,
        ) -> Stream<ReconcileOut>
        where
            M: Fn(&Es) -> Option<Measure> + Clone + 'static,
            F: Fn(&Desk<Es>) -> Standing + 'static,
        {
            let (settlements, cashflows, holdings, marks, sweep) = (
                settlements.handle(),
                cashflows.handle(),
                holdings.handle(),
                marks.handle(),
                sweep.handle(),
            );
            self.wire(move |b, fills| {
                b.reconcile_op(
                    fills,
                    settlements,
                    cashflows,
                    holdings,
                    marks,
                    sweep,
                    (config, measure, read),
                )
            })
        }
    }

    pub trait ReadingNodes {
        fn switch_op<F>(
            &self,
            clear: &Stream<()>,
            day_start: Duration,
            restored: Option<Snapshot<Risk>>,
            assess: F,
        ) -> Stream<Assessed<Risk>>
        where
            F: Fn(&mut Switch<Risk>, NanoTime, &usize) -> Breaches<Risk> + 'static;
    }

    impl ReadingNodes for Stream<Burst<usize>> {
        fn switch_op<F>(
            &self,
            clear: &Stream<()>,
            day_start: Duration,
            restored: Option<Snapshot<Risk>>,
            assess: F,
        ) -> Stream<Assessed<Risk>>
        where
            F: Fn(&mut Switch<Risk>, NanoTime, &usize) -> Breaches<Risk> + 'static,
        {
            let clear = clear.handle();
            self.wire(move |b, readings| {
                b.switch_op(readings, clear, (day_start, restored, assess))
            })
        }
    }

    // Two lots bought at the first tick, at a mark of 5001; at the second the
    // venue says it holds three, and a cashflow lands. One tick later the
    // difference has outlived the grace with nothing new arriving: the fold is
    // re-based and the switch latches on the mismatch. The operator clears
    // at the fourth tick, with nothing standing.
    //
    // `position_op` and `reconcile_op` sit side by side on one fills stream
    // here ONLY so that every op is spelled once on every tier: it is the
    // pairing execution/CLAUDE.md forbids in a real graph (two folds of the
    // same fills, one re-based and one not), and the expected rows below
    // show exactly that divergence — the position's net stays at two while
    // the reconciled net becomes three.
    wingfoil::nitro! {
        fn surface_risk(g: &GraphBuilder) -> Stream<Vec<(NanoTime, RiskCycle)>> {
            let count = g.ticker(P).count();
            let clock = count.map(|_| ());
            let fills = count.map_filter(|c: &u64| (es_fill(), *c == 1));
            let settlements = count.map_filter(|_| (Burst::<Fill<Es>>::new(), false));
            let cashflows = count.map_filter(|c: &u64| (es_cashflow(), *c == 2));
            let holdings = count.map_filter(|c: &u64| (es_holdings(), *c == 2));
            let marks = count.map_filter(|c: &u64| (es_marks(), *c == 1));
            let clear = count.map_filter(|c: &u64| ((), *c == 4));
            let position = fills.position_op(&settlements, &cashflows, es_measure, es_net);
            let reconciled = fills.reconcile_op(
                &settlements,
                &cashflows,
                &holdings,
                &marks,
                &clock,
                grace(),
                es_measure,
                es_standing,
            );
            let readings = reconciled.map(|(mismatches, _): &ReconcileOut| one(mismatches.len()));
            let switch = readings.switch_op(&clear, Duration::ZERO, None, es_assess);
            let all = position.join3(
                &reconciled,
                &switch,
                |p: &Qty, r: &ReconcileOut, s: &Assessed<Risk>| (*p, r.clone(), *s),
            );
            let out = all.with_time().accumulate();
            out
        }
    }

    /// One cycle, condensed: the position node's net; the reconciler's
    /// standing and how many mismatches it found; the switch's stance, what
    /// it holds latched and what a clear answered.
    type RiskRow = (
        NanoTime,
        Qty,
        Standing,
        usize,
        Stance,
        Breaches<Risk>,
        Option<bool>,
    );

    fn risk_row((at, (net, (mismatches, standing), switch)): &(NanoTime, RiskCycle)) -> RiskRow {
        (
            *at,
            *net,
            *standing,
            mismatches.len(),
            switch.stance,
            switch.latched,
            switch.cleared.map(|cleared| cleared.is_ok()),
        )
    }

    #[test]
    fn risk_surface_three_engine_parity() {
        let run = RunFor::Cycles(5);
        let (mut runner, out) = surface_risk::interpreted();
        runner.run(HISTORICAL, run).unwrap();
        let interp = runner.value(out);

        let tick = |n: u64| NanoTime::new(n * 10_000_000);
        let latched: Breaches<Risk> = [Risk::Mismatch].into_iter().collect();
        let (two, three) = (qty("2"), qty("3"));
        let none = Breaches::NONE;
        let expected: Vec<RiskRow> = vec![
            (
                tick(0),
                two,
                (false, 0, 0, two),
                0,
                Stance::Open,
                none,
                None,
            ),
            (tick(1), two, (true, 1, 0, two), 0, Stance::Open, none, None),
            (
                tick(2),
                two,
                (true, 0, 1, three),
                1,
                Stance::Halted,
                latched,
                None,
            ),
            (
                tick(3),
                two,
                (true, 0, 1, three),
                0,
                Stance::Open,
                none,
                Some(true),
            ),
            (
                tick(4),
                two,
                (true, 0, 1, three),
                0,
                Stance::Open,
                none,
                None,
            ),
        ];
        assert_eq!(interp.iter().map(risk_row).collect::<Vec<_>>(), expected);

        let (compiled,) = surface_risk::compiled(HISTORICAL, run).unwrap();
        assert_eq!(
            interp, compiled,
            "interpreted vs compiled drift in surface_risk"
        );

        let g = GraphBuilder::new();
        let island = surface_risk::nested(&g);
        let mut r = g.build();
        r.run(HISTORICAL, run).unwrap();
        assert_eq!(
            interp,
            r.value(&island),
            "interpreted vs nested drift in surface_risk"
        );
    }
}
